// Pinhão e cremalheira — modelo puro.
// Topologia: base fixa (z=0) -> duas sapatas-guia em U (x=±[30,48]) -> cremalheira desliza em x.
// Base -> dois mancais traseiros (y=-44..-32 e -80..-68) -> eixo ao longo de y -> pinhão em balanço (y=-10..10).
// Plano de engrenamento x-z; frame do perfil u=x, v=z, a=-y. Câmera vê de +x,+y,+z: mancais ficam atrás do pinhão.
import { spurGear } from '/leitor/mechanics.mjs'
export const M = 4, TEETH = 20, BACKLASH = 0.04 * M
export const gear = spurGear({ teeth: TEETH, module: M, backlash: BACKLASH, samples: 10 })
export const R = gear.pitchRadius            // 40
export const PITCH = Math.PI * M
export const ZC = 75, ZP = ZC - R            // pitch line of rack
export const RACK = { L: 22 * PITCH, y0: -12, y1: 12, zb: 14, zr: ZP - 1.25 * M, zt: ZP + M }
export const GEARY = [-10, 10]
export const SHOE = { x0: 30, x1: 48, y: 28, top: 28 }
export const STOP = { w: 12, y: 16, z0: 12, z1: 37 }
export const SHAFT = { r: 8, y0: -88, y1: 18 }
export const BEARINGS = [[-44, -32], [-80, -68]]
export const BORE = 8.15
// Guia linear: sapata em U (perfil y-z extrudado em x de SHOE.x0 a SHOE.x1) com réguas de bronze.
// A cremalheira (y=±12, base z=14) corre sobre o patim do fundo e entre as réguas laterais.
export const GUIDE = { plate: 6, base: 28, jawOut: 22, jawIn: 13.4, floor: 12.6, jawTop: 27,
  padIn: 12.05, padTop: 28.2, seatTop: 13.95, screwY: 17.7, screwR: 2.2 }
// Janela de inspeção (corte fixo no mundo): remove o material da cremalheira com y > face do pinhão em |x| < CUT.x.
export const CUT = { x: 26, y: GEARY[1] }
export const XMAX = RACK.L / 2 - SHOE.x1
export const THMAX = XMAX / R
const ALPHA = Math.PI / 9

export function initial() { return { theta: 0, dir: 1, playing: false, speed: 0.6, inspect: false, blocked: false } }
const clampT = t => Math.max(-THMAX, Math.min(THMAX, t))
export function rackX(theta) { return R * theta }   // rolagem sem escorregamento
export function setAngle(s, deg) { const t = deg * Math.PI / 180; const c = clampT(t); return { ...s, theta: c, blocked: c !== t } }
export function setTravel(s, x) { return setAngle(s, (x / R) * 180 / Math.PI) }
export function step(s, dt) {
  if (!s.playing) return s
  let t = s.theta + s.dir * s.speed * dt
  if (t > THMAX || t < -THMAX) { t = clampT(t); return { ...s, theta: t, playing: false, blocked: true } }
  return { ...s, theta: t, blocked: false }
}
export function togglePlay(s) {
  if (!s.playing && Math.abs(s.theta - s.dir * THMAX) < 1e-9) return { ...s, blocked: true }
  return { ...s, playing: !s.playing, blocked: false }
}
export function reverse(s) { return { ...s, dir: -s.dir, blocked: false } }
export function reset(s) { return { ...initial(), inspect: s.inspect } }
export function atLimit(s) { return s.theta >= THMAX - 1e-9 ? 1 : s.theta <= -THMAX + 1e-9 ? -1 : 0 }

// Perfil da cremalheira (local x-z, relativo a x da cremalheira): dentes trapezoidais 20°.
export function rackOutline() {
  const half = (PITCH / 2 - BACKLASH) / 2, ta = Math.tan(ALPHA)
  const hT = half - M * ta, hR = half + 1.25 * M * ta, n = 11, pts = [[-RACK.L / 2, RACK.zb]]
  pts.push([RACK.L / 2, RACK.zb])
  for (let k = n - 1; k >= -n; k--) {
    const c = (k + 0.5) * PITCH  // tooth centers between gaps at k*PITCH
    pts.push([c + hR, RACK.zr], [c + hT, RACK.zt], [c - hT, RACK.zt], [c - hR, RACK.zr])
  }
  pts.push([-RACK.L / 2, RACK.zr]); pts.splice(2, 0, [RACK.L / 2, RACK.zr])
  return pts
}
const RACK_OUT = rackOutline()
// Ponto do pinhão: contorno local girado por theta em torno do eixo (0,ZC).
export function gearWorld(theta) {
  const c = Math.cos(theta), s = Math.sin(theta)
  return gear.outline.map(([u, v]) => [u * c - v * s, ZC + u * s + v * c])
}
export function rackWorld(theta) { const x = rackX(theta); return RACK_OUT.map(([u, v]) => [u + x, v]) }
function inside(p, poly) {
  let w = false
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j]
    if ((a[1] > p[1]) !== (b[1] > p[1]) && p[0] < (b[0] - a[0]) * (p[1] - a[1]) / (b[1] - a[1]) + a[0]) w = !w
  }
  return w
}
function segDist(p, a, b) {
  const dx = b[0] - a[0], dy = b[1] - a[1], L = dx * dx + dy * dy
  const t = L ? Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L)) : 0
  return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dy)
}
// Folga e pontos de contato entre os perfis reais na zona de engrenamento.
export function mesh(theta) {
  const g = gearWorld(theta).filter(p => p[1] < ZP + 2 * M && Math.abs(p[0]) < 30)
  const rk = rackWorld(theta), local = []
  for (let i = 0; i < rk.length; i++) { const a = rk[i], b = rk[(i + 1) % rk.length]; if (Math.abs(a[0]) < 34 && a[1] > RACK.zb + 1 && b[1] > RACK.zb + 1) local.push([a, b]) }
  let pen = 0, minGap = Infinity; const contacts = []
  for (const p of g) {
    if (inside(p, rk)) pen++
    let d = Infinity; for (const [a, b] of local) d = Math.min(d, segDist(p, a, b))
    minGap = Math.min(minGap, d)
    if (d < 0.3 && p[1] > RACK.zr + 0.5 && p[1] < RACK.zt - 0.2) contacts.push([p[0], p[1], d])
  }
  return { penetrations: pen, minGap, contacts }
}
export function readout(s) {
  return { deg: s.theta * 180 / Math.PI, x: rackX(s.theta), limit: atLimit(s) }
}

