import * as m from './model.mjs'
const ok = (name, passed, detail = '') => ({ name, passed: !!passed, detail })
export function verify() {
  const out = []
  const N = 61, samples = Array.from({ length: N }, (_, i) => -m.THMAX + 2 * m.THMAX * i / (N - 1))
  let pen = 0, worstGap = 0, minContacts = Infinity, at = 0
  for (const t of samples) {
    const r = m.mesh(t)
    pen += r.penetrations
    if (r.minGap > worstGap) { worstGap = r.minGap; at = t }
    minContacts = Math.min(minContacts, r.contacts.length)
  }
  out.push(ok('sem interpenetração dos perfis no curso inteiro', pen === 0, `pontos=${pen}`))
  out.push(ok('folga mínima de flanco < 0.3 mm em todo o curso', worstGap < 0.3, `pior=${worstGap.toFixed(3)} θ=${at.toFixed(3)}`))
  out.push(ok('sempre há flanco em contato na zona de engrenamento', minContacts >= 1, `min=${minContacts}`))
  // rolling without slip: arc on pitch circle equals rack advance between samples
  let slip = 0
  for (let i = 1; i < N; i++) slip = Math.max(slip, Math.abs((m.rackX(samples[i]) - m.rackX(samples[i - 1])) - m.gear.pitchRadius * (samples[i] - samples[i - 1])))
  out.push(ok('avanço = raio primitivo × Δθ (sem escorregamento)', slip < 1e-9, `erro=${slip}`))
  const pitchOk = Math.abs(m.R - m.TEETH * m.M / 2) < 1e-9 && Math.abs(m.ZC - m.R - m.ZP) < 1e-9
  out.push(ok('linha primitiva tangente ao círculo primitivo', pitchOk))
  // travel limit: stop face meets shoe face exactly at XMAX
  const stopFace = m.rackX(m.THMAX) - m.RACK.L / 2
  out.push(ok('batente encosta na sapata no limite de curso', Math.abs(stopFace + m.SHOE.x1) < 1e-9, `face=${stopFace}`))
  // play state machine reaches limit and stops
  let s = m.togglePlay(m.initial()), steps = 0
  while (s.playing && steps < 10000) { s = m.step(s, 1 / 60); steps++ }
  out.push(ok('reprodução para no limite +', !s.playing && m.atLimit(s) === 1 && s.blocked, `passos=${steps}`))
  const s2 = m.togglePlay(s)
  out.push(ok('reproduzir no limite é bloqueado', !s2.playing && s2.blocked))
  let s3 = m.togglePlay(m.reverse(s)); const th0 = s3.theta; s3 = m.step(s3, 0.5)
  out.push(ok('reversão afasta do limite', s3.playing && s3.theta < th0))
  const s4 = m.setAngle(m.initial(), 400)
  out.push(ok('ângulo manual é limitado ao curso', Math.abs(s4.theta - m.THMAX) < 1e-12 && s4.blocked))
  // engagement: rack still under pinion contact zone at both limits
  const cover = [m.THMAX, -m.THMAX].every(t => m.rackX(t) - m.RACK.L / 2 < -30 && m.rackX(t) + m.RACK.L / 2 > 30)
  out.push(ok('cremalheira cobre a zona de contato nos dois limites', cover))
  const ov = Math.min(m.RACK.y1, m.GEARY[1]) - Math.max(m.RACK.y0, m.GEARY[0])
  out.push(ok('largura de face engrenada > 15 mm', ov > 15, `sobreposição=${ov}`))
  const shaftOk = m.BEARINGS.every(([a, b]) => m.SHAFT.y0 < a && m.SHAFT.y1 > b) && m.SHAFT.r < m.BORE && m.BORE - m.SHAFT.r < 0.5 && m.SHAFT.y0 < m.GEARY[0] && m.SHAFT.y1 > m.GEARY[1]
  out.push(ok('eixo atravessa os dois mancais e o pinhão', shaftOk))
  const shoeClear = m.SHOE.top < m.RACK.zr && m.STOP.z1 < m.ZC - m.gear.tipRadius * 0.5
  out.push(ok('sapatas abaixo da raiz dos dentes', shoeClear))
  return out
}
// Guia linear em 3D: réguas abraçam as faces da cremalheira, patim sustenta a base, janela contém o contato.
export function verifyExtra1() {
  const out = [], g = m.GUIDE, N = 41
  const lat = g.padIn - m.RACK.y1
  out.push(ok('folga lateral régua–cremalheira entre 0 e 0.2 mm', lat > 0 && lat < 0.2, `folga=${lat.toFixed(3)}`))
  const vert = m.RACK.zb - g.seatTop
  out.push(ok('cremalheira apoiada no patim (folga vertical < 0.1 mm)', vert >= 0 && vert < 0.1, `folga=${vert.toFixed(3)}`))
  const wrapH = Math.min(g.padTop, m.RACK.zr) - Math.max(g.seatTop, m.RACK.zb)
  out.push(ok('réguas cobrem a lateral da cremalheira > 8 mm', wrapH > 8, `altura=${wrapH.toFixed(2)}`))
  out.push(ok('réguas abaixo do pé dos dentes', g.padTop < m.RACK.zr && g.jawTop < g.padTop))
  // sliding engagement: rack spans both shoes along x during the whole travel
  let minEng = Infinity
  for (let i = 0; i < N; i++) {
    const x = m.rackX(-m.THMAX + 2 * m.THMAX * i / (N - 1))
    for (const [a, b] of [[m.SHOE.x0, m.SHOE.x1], [-m.SHOE.x1, -m.SHOE.x0]]) minEng = Math.min(minEng, Math.min(b, x + m.RACK.L / 2) - Math.max(a, x - m.RACK.L / 2))
  }
  out.push(ok('cremalheira engata nas duas sapatas em todo o curso', minEng >= m.SHOE.x1 - m.SHOE.x0 - 1e-9, `min=${minEng.toFixed(2)}`))
  // stop at limit overlaps the shoe end face in y-z (real face contact, not an edge)
  const yOv = Math.min(m.STOP.y, g.jawOut) - Math.max(-m.STOP.y, -g.jawOut)
  const zOv = Math.min(m.STOP.z1, g.jawTop) - Math.max(m.STOP.z0, 0)
  out.push(ok('batente cobre a face da sapata (área de contato)', yOv > 20 && zOv > 8, `y=${yOv} z=${zOv}`))
  let outside = 0, total = 0
  for (let i = 0; i < N; i++) for (const [X] of m.mesh(-m.THMAX + 2 * m.THMAX * i / (N - 1)).contacts) { total++; if (Math.abs(X) > m.CUT.x - 2) outside++ }
  out.push(ok('contatos sempre dentro da janela de inspeção', total > 0 && outside === 0, `fora=${outside}/${total}`))
  out.push(ok('janela não invade as sapatas', m.CUT.x < m.SHOE.x0 && m.CUT.y === m.GEARY[1]))
  return out
}

