import * as m from './model.mjs'
import { camera, scene, insetSvg, frameHeight } from './geometry.mjs'

export function mount(root, env = {}) {
  let s = m.initial(), raf = 0, last = 0, visible = true, W = 900, H = 520, P = null
  const maxDeg = Math.floor(m.THMAX * 180 / Math.PI)
  root.innerHTML = `<div class="pr">
  <div class="pr-stage"><svg class="pr-art iso" role="img" aria-label="Montagem isométrica de pinhão e cremalheira"></svg>
    <div class="pr-inset" hidden></div></div>
  <div class="pr-controls">
    <button id="play" type="button">Reproduzir</button>
    <button id="reverse" type="button">Inverter sentido</button>
    <button id="inspect" type="button" aria-pressed="false">Inspecionar contato</button>
    <button id="reset" type="button">Reiniciar</button>
    <label class="pr-range">Ângulo do pinhão <input id="angle" type="range" min="${-maxDeg - 1}" max="${maxDeg + 1}" step="1" value="0"></label>
  </div>
  <p id="status" class="pr-status" role="status" aria-live="polite"></p>
  <ul class="pr-legend">
    <li><b>Pinhão</b> z = ${m.TEETH}, módulo ${m.M} mm, raio primitivo r = ${m.R} mm</li>
    <li><b>Cremalheira</b> passo p = π·m = ${m.PITCH.toFixed(2)} mm; curso ±${m.XMAX.toFixed(1)} mm até os batentes</li>
    <li><b>Eixo</b> em balanço sobre dois mancais de rolamento; <b>guia</b> por duas sapatas em U</li>
  </ul></div>`
  const $ = sel => root.querySelector(sel)
  const art = $('.pr-art'), inset = $('.pr-inset'), status = $('#status'), range = $('#angle')
  const layout = () => {
    const w = Math.max(320, Math.min(1000, root.clientWidth || 900))
    W = w; H = w < 560 ? frameHeight(w) : Math.round(w * 0.56)
    P = camera(W, H); art.setAttribute('viewBox', `0 0 ${W} ${H}`)
  }
  const render = () => {
    art.innerHTML = scene(s, P)
    inset.hidden = !s.inspect
    if (s.inspect) inset.innerHTML = insetSvg(s.theta)
    const r = m.readout(s), dir = s.dir > 0 ? 'avança para +x' : 'recua para −x'
    let txt = `θ = ${r.deg.toFixed(1)}° · avanço x = r·θ = ${r.x.toFixed(1)} mm · ${dir}`
    if (r.limit) txt += ` · Limite de curso ${r.limit > 0 ? '+' : '−'}: batente encostado na guia`
    if (s.blocked && !r.limit) txt += ' · bloqueado'
    if (s.blocked && r.limit && !s.playing) txt += ' — inverta o sentido'
    if (s.inspect) txt += ` · ${m.mesh(s.theta).contacts.length > 0 ? 'Contato nos flancos visível' : 'sem contato'}`
    status.textContent = txt
    $('#play').textContent = s.playing ? 'Pausar' : 'Reproduzir'
    $('#inspect').setAttribute('aria-pressed', String(s.inspect))
    $('#inspect').textContent = s.inspect ? 'Ocultar inspeção' : 'Inspecionar contato'
    range.value = String(Math.round(r.deg))
  }
  const frame = t => {
    raf = 0
    if (!s.playing || !visible) return
    const dt = Math.min(0.05, Math.max(0, (t - last) / 1000)); last = t
    s = m.step(s, dt); render()
    if (s.playing) raf = requestAnimationFrame(frame)
  }
  const start = () => { if (!raf && s.playing && visible) { last = performance.now(); raf = requestAnimationFrame(frame) } }
  const stop = () => { if (raf) cancelAnimationFrame(raf); raf = 0 }
  const on = (id, f) => $(id).addEventListener('click', () => { f(); render(); s.playing ? start() : stop() })
  on('#play', () => { s = m.togglePlay(s) })
  on('#reverse', () => { s = m.reverse(s) })
  on('#inspect', () => { s = { ...s, inspect: !s.inspect } })
  on('#reset', () => { s = m.reset(s) })
  range.addEventListener('input', () => { stop(); s = m.setAngle({ ...s, playing: false }, Number(range.value)); render() })
  const env2 = e => { const d = e.detail || {}; if (d.visible === false) { visible = false; stop() } else { visible = true; start() } }
  root.addEventListener('figure:environment', env2)
  const ro = new ResizeObserver(() => { const old = W; layout(); if (W !== old) render() })
  ro.observe(root)
  layout(); render()
  return () => { stop(); ro.disconnect(); root.removeEventListener('figure:environment', env2); root.innerHTML = '' }
}

