import * as k from '/kit/iso-kit.mjs'
import * as G from '/kit/lathe.mjs'
import { mPrism, mItems, mSvg, mPose, mArc, mClip, mView, mLight, mBand, mUnit, mDot, mFace, mHatch } from '/kit/facets.mjs'
import { orderSurfaces, planeThrough } from '/leitor/occlusion.mjs'
import * as m from './model.mjs'

const ZONE = 30, ZSPLIT = m.RACK.zt + 1
const clipSeg = (a, b, hs) => { for (const [n, d] of hs) { const fa = mDot(a, n) - d, fb = mDot(b, n) - d
  if (fa > 0 && fb > 0) return null
  if (fa > 0 || fb > 0) { const p = a.map((v, i) => v + (b[i] - v) * fa / (fa - fb)); if (fa > 0) a = p; else b = p } } return [a, b] }
// Convert visible single-ring faces to BSP items (faces + outline segments), clipped to half-spaces.
function bspItems(mesh, mat, P, hs, out) {
  const V = mView(P), L = mLight(P), vis = n => n && mDot(n, V) > 1e-6
  for (const f of mesh.faces) {
    if (!vis(f.n) || f.rings.length !== 1) continue
    const ring = hs.reduce((r, [n, d]) => r.length > 2 ? mClip(r, n, d) : r, f.rings[0])
    if (ring.length < 3) continue
    out.push({ points: ring, mat, band: mBand(mDot(mUnit(f.n), L)) })
    for (const e of f.edges) {
      if (e.nb === false) continue
      const cls = !vis(e.nb) ? 'iso-line iso-edge' : (e.own && mDot(f.n, e.nb) < 0.94) ? 'iso-line iso-crease' : ''
      if (!cls) continue
      const s = clipSeg(e.a, e.b, hs); if (s) out.push({ segment: true, points: s, mat, cls })
    }
  }
}
function bspSvg(list, planes, P) {
  const frags = orderSurfaces(list, { planes, view: mView(P) })
  let html = '', cur = null
  for (const f of frags) {
    if (f.mat !== cur) { if (cur) html += '</g>'; html += `<g class="${f.mat}">`; cur = f.mat }
    const d = k.pathOf(f.points.map(p => k.iso(p, P)), !f.segment)
    html += f.segment ? `<path class="${f.cls}" d="${d}"/>` : f.band === 4 ? `<path class="iso-top frag" d="${d}"/>` : `<path class="iso-shade frag" data-shade="${f.band}" d="${d}"/>`
  }
  return html + (cur ? '</g>' : '')
}
// Partition planes: actual rack flanks near the mesh plus tooth top/root planes.
function rackPlanes(x) {
  const o = m.rackOutline(), pl = []
  for (let i = 0; i < o.length; i++) {
    const a = o[i], b = o[(i + 1) % o.length]
    if (Math.abs(a[1] - b[1]) < 1e-6 || Math.min(a[1], b[1]) < m.RACK.zb + 1) continue
    if (Math.abs((a[0] + b[0]) / 2 + x) > ZONE + 6) continue
    pl.push(planeThrough([a[0] + x, 0, a[1]], [b[0] + x, 0, b[1]], [a[0] + x, 1, a[1]]))
  }
  pl.push(planeThrough([0, 0, m.RACK.zt], [1, 0, m.RACK.zt], [0, 1, m.RACK.zt]), planeThrough([0, 0, m.RACK.zr], [1, 0, m.RACK.zr], [0, 1, m.RACK.zr]))
  return pl.slice(0, 32)
}
// Inspection window: world-fixed cut face of the rack at y = CUT.y, with hatching, and the left window wall.
function cutMeshes(x) {
  const C = m.CUT.x, y = m.CUT.y, Y = m.RACK.y1
  let ring = m.rackWorld(0).map(([u, v]) => [u + x, y, v])
  ring = mClip(mClip(ring, [1, 0, 0], C), [-1, 0, 0], C)
  const hatch = mHatch([ring.map(p => [p[0], p[2]])], Math.PI / 4, 3).map(([a, b]) => [[a[0], y + .05, a[1]], [b[0], y + .05, b[1]]])
  const face = mFace(ring, [0, 1, 0], ring.map(() => null), { fill: 'cut', lines: hatch })
  const h = Math.max(...ring.filter(p => Math.abs(p[0] + C) < 1e-6).map(p => p[2]), m.RACK.zr)
  const wall = mFace([[-C, y, m.RACK.zb], [-C, Y, m.RACK.zb], [-C, Y, h], [-C, y, h]], [1, 0, 0], [null, null, null, null], { fill: 'cut' })
  return { face: { faces: [face], tone: 'hi' }, wall: { faces: [wall], tone: 'hi' } }
}

const FG = (x = 0) => ({ o: [x, 0, m.ZC], u: [1, 0, 0], v: [0, 0, 1], a: [0, -1, 0] })   // y = -s
const FR = { o: [0, 0, 0], u: [1, 0, 0], v: [0, 0, 1], a: [0, -1, 0] }
const FX = x => ({ o: [x, 0, 0], a: [1, 0, 0], u: [0, 1, 0], v: [0, 0, 1] })
const circ = (cx, cy, r, n = 28) => mArc(cx, cy, r, 0, 2 * Math.PI, n).slice(0, n)

// Static meshes (built once, posed per frame).
const holes = Array.from({ length: 5 }, (_, i) => circ(24 * Math.cos(i * 1.2566 + .63), 24 * Math.sin(i * 1.2566 + .63), 6, 18))
const GEAR = mPrism([m.gear.outline, circ(0, 0, m.SHAFT.r, 24), ...holes], FG(), -m.GEARY[1], -m.GEARY[0], { tone: 'hi' })
const WASHER = mPrism([circ(0, 0, 13, 32)], FG(), -11.5, -10, { tone: 'mid' })
const NUT = mPrism([circ(0, 0, 10, 6)], FG(), -17, -11.5, { tone: 'mid' })
const RACKM = mPrism([m.rackOutline()], FR, -m.RACK.y1, -m.RACK.y0, { tone: 'hi' })
const stopRing = x0 => [[x0, m.STOP.z0], [x0 + m.STOP.w, m.STOP.z0], [x0 + m.STOP.w, m.STOP.z1], [x0, m.STOP.z1]]
const STOPL = mPrism([stopRing(-m.RACK.L / 2 - m.STOP.w)], FR, -m.STOP.y, m.STOP.y, { tone: 'mid' })
const STOPR = mPrism([stopRing(m.RACK.L / 2)], FR, -m.STOP.y, m.STOP.y, { tone: 'mid' })
const GD = m.GUIDE
const shoeU = [[-GD.base, 0], [GD.base, 0], [GD.base, GD.plate], [GD.jawOut, GD.plate], [GD.jawOut, GD.jawTop], [GD.jawIn, GD.jawTop], [GD.jawIn, GD.floor],
  [-GD.jawIn, GD.floor], [-GD.jawIn, GD.jawTop], [-GD.jawOut, GD.jawTop], [-GD.jawOut, GD.plate], [-GD.base, GD.plate]]
const padR = sg => [[sg * GD.padIn, GD.floor], [sg * GD.jawIn, GD.floor], [sg * GD.jawIn, GD.padTop], [sg * GD.padIn, GD.padTop]]
const seat = [[-GD.padIn, GD.floor], [GD.padIn, GD.floor], [GD.padIn, GD.seatTop], [-GD.padIn, GD.seatTop]]
const SHOES = [-1, 1].map(sg => {
  const x0 = sg > 0 ? m.SHOE.x0 : -m.SHOE.x1, L = m.SHOE.x1 - m.SHOE.x0, F = FX(x0)
  return { x0, body: mPrism([shoeU], F, 0, L, { tone: 'mid' }), padB: mPrism([padR(-1)], F, 0, L, { tone: 'mid' }),
    padF: mPrism([padR(1)], F, 0, L, { tone: 'mid' }), seat: mPrism([seat], F, 0, L, { tone: 'mid' }) }
})
const YB = m.RACK.y1
const backReg = [[[[0, 1, 0], YB]], [[[0, -1, 0], -YB]]]
function shoeBackSvg(P) {
  return SHOES.map(s => { const b = items(s.body, P, { regions: backReg })
    return g_('mat-dark', mSvg(b[0])) + g_('mat-bronze', draw(s.seat, P), draw(s.padB, P)) }).join('')
}
function shoeFrontSvg(P) {
  return SHOES.map(s => { const b = items(s.body, P, { regions: backReg })
    const screws = [s.x0 + 4.5, s.x0 + 13.5].map(x => k.solidSvg(k.cylinder(x, GD.screwY, GD.screwR, GD.jawTop, 1.6, P, 12), { tone: 'mid' })).join('')
    return g_('mat-dark', mSvg(b[1])) + g_('mat-bronze', draw(s.padF, P)) + g_('mat-steel', screws) }).join('')
}
const g_ = (cls, ...s) => `<g class="${cls}">${s.join('')}</g>`
const pedRing = [[-28, 0], [28, 0], [28, 8], [16, 14], ...mArc(0, m.ZC, 18, 0, Math.PI, 16).map(([u, v]) => [Math.max(-16, Math.min(16, u)), v]), [-16, 14], [-28, 8]]
const PEDS = m.BEARINGS.map(([y0, y1]) => ({
  body: mPrism([pedRing, circ(0, m.ZC, 12, 28)], FR, -y1, -y0, { tone: 'mid' }),
  race: mPrism([circ(0, 0, 12, 28), circ(0, 0, m.BORE, 24)], FG(), -y1 - 1, -y0 + 1, { tone: 'hi' }),
}))

// Rotate a mesh about the shaft axis (parallel to y through x=0,z=ZC) — vertices and normals.
function rotY(mesh, th, dx = 0) {
  const c = Math.cos(th), s = Math.sin(th)
  const P = p => { const x = p[0], z = p[2] - m.ZC; return [x * c - z * s + dx, p[1], m.ZC + x * s + z * c] }
  const N = n => n && [n[0] * c - n[2] * s, n[1], n[0] * s + n[2] * c]
  return { ...mesh, faces: mesh.faces.map(f => ({ ...f, rings: f.rings.map(r => r.map(P)), n: N(f.n), edges: f.edges.map(e => ({ ...e, a: P(e.a), b: P(e.b), nb: N(e.nb) })) })) }
}
const items = (mesh, P, opts) => mItems(mesh, P, opts)
const draw = (mesh, P) => mSvg(items(mesh, P)[0])
const sidesCaps = mesh => [{ ...mesh, faces: mesh.faces.slice(2) }, { ...mesh, faces: mesh.faces.slice(0, 2) }]
const shaftSeg = (y0, y1, P) => k.solidSvg(G.lathe([[0, m.SHAFT.r], [y1 - y0, m.SHAFT.r]], G.frameAlong([0, y0, m.ZC], [0, 1, 0]), P), { tone: 'mid' })

// Whole assembly over its full travel: base, rack + stops at both limits, pedestals, pinion, nut.
const RX = m.XMAX + m.RACK.L / 2 + m.STOP.w + 6
const FULL = [...k.boxCorners({ x: -202, y: -102, w: 404, d: 140 }, -12, 0),
  ...k.boxCorners({ x: -RX, y: -18, w: 2 * RX, d: 36 }, 0, 42),
  ...k.boxCorners({ x: -46, y: -92, w: 92, d: 114 }, 0, m.ZC + 46)]
const VIEW = { azimuth: 52, elevation: 26 }
const padFor = w => w < 560 ? 12 : 18
// Height that lets the full assembly fit at the width-limited scale (used for the mobile viewBox).
export function frameHeight(w) {
  const pad = padFor(w), P = k.fitProjection(FULL, w, w * 4, { pad, ...VIEW })
  const ys = FULL.map(p => k.iso(p, P)[1])
  return Math.ceil(Math.max(...ys) - Math.min(...ys) + 2 * pad + 8)
}
export function camera(w, h) {
  return k.fitProjection(FULL, w, h, { pad: padFor(w), ...VIEW })
}

export function scene(state, P) {
  const th = state.theta, x = m.rackX(th), out = []
  const g_ = (cls, ...s) => `<g class="${cls}">${s.join('')}</g>`
  out.push(g_('mat-base', k.solidSvg(k.slabOf({ x: -200, y: -100, w: 400, d: 136, r: 6 }, -10, 10, P, 8, 1.5), { tone: 'lo' })))
  for (const [bx, by] of [[-180, -85], [180, -85], [-180, 22], [180, 22]]) out.push(g_('mat-dark', k.solidSvg(k.cylinder(bx, by, 4, 0, 2, P, 12), { tone: 'mid' })))
  out.push(g_('mat-steel', shaftSeg(m.SHAFT.y0, -80, P)))
  out.push(g_('mat-frame', draw(PEDS[1].body, P)), g_('mat-bronze', draw(rotY(PEDS[1].race, 0), P)))
  out.push(g_('mat-steel', shaftSeg(-68, -44, P)))
  out.push(g_('mat-frame', draw(PEDS[0].body, P)), g_('mat-bronze', draw(PEDS[0].race, P)))
  { const L2 = m.RACK.L / 2, q = [[x - L2, -m.RACK.y1 - 2], [x + L2, -m.RACK.y1 - 2], [x + L2, m.RACK.y1 + 2], [x - L2, m.RACK.y1 + 2]]
    out.push(`<path class="shadow" d="${k.pathOf(q.map(([a, b]) => k.iso([a, b, 0.05], P)), true)}"/>`) }
  out.push(shoeBackSvg(P))
  out.push(g_('mat-steel', shaftSeg(-32, -10, P)))
  out.push(g_('mat-dark', draw(mPose(STOPL, 0, [x, 0, 0]), P)))
  const rk = mPose(RACKM, 0, [x, 0, 0]), [rs, rc] = sidesCaps(rk), Y = m.CUT.y, C = m.CUT.x
  // rack sides outside the mesh zone and behind the pinion face
  const far = items(rs, P, { regions: [[[[1, 0, 0], -ZONE], [[0, 1, 0], Y]], [[[-1, 0, 0], -ZONE], [[0, 1, 0], Y]]] })
  out.push(g_('mat-steel', mSvg([...far[0], ...far[1]])))
  // mesh zone: rack tooth faces and lower pinion faces ordered by the real flank planes
  const g = rotY(GEAR, th), [gs, gc] = sidesCaps(g), list = []
  bspItems(rs, 'mat-steel', P, [[[1, 0, 0], ZONE], [[-1, 0, 0], ZONE], [[0, 1, 0], Y]], list)
  bspItems(gs, 'mat-gear', P, [[[0, 0, 1], ZSPLIT]], list)
  out.push(bspSvg(list, rackPlanes(x), P))
  const up = items(gs, P, { regions: [[[[0, 0, -1], -ZSPLIT]]] })
  out.push(g_('mat-gear', mSvg(up[0])))
  const cut = state.inspect ? cutMeshes(x) : null
  if (cut) out.push(g_('mat-steel', draw(cut.face, P)))
  out.push(g_('mat-gear', draw(gc, P)))
  // rack material in front of the pinion face (y > CUT.y); inspection opens a window |x| < CUT.x
  const frontRegs = state.inspect ? [[[[1, 0, 0], -C], [[0, -1, 0], -Y]], [[[-1, 0, 0], -C], [[0, -1, 0], -Y]]] : [[[[0, -1, 0], -Y]]]
  if (cut) out.push(g_('mat-steel', draw(cut.wall, P)))
  out.push(g_('mat-steel', mSvg(items(rs, P, { regions: frontRegs }).flat())))
  const capRegs = state.inspect ? [[[[1, 0, 0], -C]], [[[-1, 0, 0], -C]]] : [[]]
  out.push(g_('mat-steel', mSvg(items(rc, P, { regions: capRegs }).flat())))
  out.push(shoeFrontSvg(P))
  out.push(g_('mat-dark', draw(mPose(STOPR, 0, [x, 0, 0]), P)))
  out.push(g_('mat-steel', draw(rotY(WASHER, th), P), draw(rotY(NUT, th), P)))
  if (state.inspect) out.push(overlay(th, P))
  return out.join('')
}

function overlay(th, P) {
  const y = m.CUT.y + .3, w = (X, Z) => k.iso([X, y, Z], P)
  const pl = k.pathOf([w(-m.CUT.x, m.ZP), w(m.CUT.x, m.ZP)])
  const a = Math.PI / 9, L = 22
  const loa = k.pathOf([w(-L * Math.cos(a), m.ZP + L * Math.sin(a)), w(L * Math.cos(a), m.ZP - L * Math.sin(a))])
  const arc = k.pathOf(mArc(0, m.ZC, m.R, -2.3, -0.84, 30).map(([u, v]) => w(u, v)))
  const dots = m.mesh(th).contacts.map(([X, Z]) => { const [sx, sy] = w(X, Z); return `<circle class="contact" cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="4.6"/>` }).join('')
  return `<path class="pitch" d="${pl}"/><path class="pitch" d="${arc}"/><path class="loa" d="${loa}"/>${dots}`
}

// Orthographic end view (x-z), magnified at the mesh.
export function insetSvg(th, W = 220, H = 150) {
  const s = W / 60, X = x => (W / 2 + x * s).toFixed(1), Z = z => (H * .55 - (z - m.ZP) * s).toFixed(1)
  const poly = pts => 'M' + pts.map(([x, z]) => X(x) + ' ' + Z(z)).join('L') + 'Z'
  const g = m.gearWorld(th)
  const r = m.rackWorld(th).map(([x, z]) => [Math.max(-40, Math.min(40, x)), Math.max(m.ZP - 22, z)])
  const c = m.mesh(th).contacts.map(([x, z]) => `<circle class="contact" cx="${X(x)}" cy="${Z(z)}" r="2.6"/>`).join('')
  const a = Math.PI / 9
  return `<svg viewBox="0 0 ${W} ${H}" class="inset" role="img" aria-label="Vista lateral do engrenamento">
<path class="in-rack" d="${poly(r)}"/><path class="in-gear" d="${poly(g)}"/>
<path class="pitch" d="M0 ${Z(m.ZP)}H${W}"/><path class="loa" d="M${X(-25 * Math.cos(a))} ${Z(m.ZP + 25 * Math.sin(a))}L${X(25 * Math.cos(a))} ${Z(m.ZP - 25 * Math.sin(a))}"/>${c}
<text x="6" y="14" class="in-t">detalhe opcional · vista lateral ×${(s / 1).toFixed(1)}</text></svg>`
}
